What does this program print?

```c
#include <stdio.h>

void f(int a) {
    a = 5;
}

int main(void) {
    int b = 1;
    f(b);
    printf("%d\n", b);
    return 0;
}
```

What does this program print?

```c
#include <stdio.h>

void g(int *p) {
    int z = 7;
    p = &z;
    *p = 9;
}

int main(void) {
    int x = 3;
    g(&x);
    printf("%d\n", x);
    return 0;
}
```

